use actix_files::{Files, NamedFile};
use actix_web::{
    CustomizeResponder, Either, HttpMessage, HttpRequest, HttpResponse, Responder,
    dev::HttpServiceFactory,
    error::ErrorNotFound,
    get,
    http::header::{self, AcceptEncoding, ContentEncoding, ContentType, Encoding},
    web::{self, Data},
};
use std::{
    fs::File,
    io::{self, Read},
    path::{Path, PathBuf},
};

/// Folder uploaded to the server next to the binary. It must contain `img/` and
/// the `html/` docs generated by `build.rs`
#[derive(Debug, Clone)]
pub struct StaticDir(PathBuf);

impl StaticDir {
    pub fn new(root: impl Into<PathBuf>) -> io::Result<Self> {
        let root = root.into();

        for dir in ["img", "html"] {
            if !root.join(dir).is_dir() {
                return Err(io::Error::new(
                    io::ErrorKind::NotFound,
                    format!("Static folder {root:?} has no `{dir}` directory. Check STATIC_DIR"),
                ));
            }
        }

        Ok(Self(root))
    }

    /// Reads `STATIC_DIR`, falling back to the workspace root where `build.rs`
    /// writes the docs and where the images are versioned
    pub fn from_env() -> io::Result<Self> {
        match std::env::var_os("STATIC_DIR") {
            Some(root) => Self::new(root),
            None => Self::new(Path::new(env!("CARGO_MANIFEST_DIR")).parent().unwrap()),
        }
    }

    pub fn path(&self) -> &Path {
        &self.0
    }

    /// Serves every file under `img/`, so new images only need to be uploaded
    pub fn images(&self) -> impl HttpServiceFactory + 'static {
        Files::new("", self.0.join("img"))
            .use_etag(false)
            .use_last_modified(false)
    }
}

/// Serves the generated docs of a champion, item or rune, such as
/// `/docs/champions/Aatrox`. Pages are stored with brotli, and are decompressed
/// only for clients that do not accept it
#[get("/{kind}/{name}")]
pub async fn serve_docs(
    req: HttpRequest,
    path: web::Path<(String, String)>,
    statics: Data<StaticDir>,
) -> actix_web::Result<Either<CustomizeResponder<NamedFile>, HttpResponse>> {
    let (kind, name) = path.into_inner();

    // Pages are named after enum variants, which also rejects path traversal
    if !matches!(kind.as_str(), "champions" | "items" | "runes")
        || !name.bytes().all(|byte| byte.is_ascii_alphanumeric())
    {
        return Err(ErrorNotFound("Unknown docs page"));
    }

    let file = statics
        .0
        .join("html")
        .join(kind)
        .join(name)
        .with_extension("html.br");

    let accepts_brotli = req
        .get_header::<AcceptEncoding>()
        .and_then(|accept| accept.negotiate([Encoding::brotli(), Encoding::identity()].iter()))
        == Some(Encoding::brotli());

    if accepts_brotli {
        let page = NamedFile::open_async(file)
            .await?
            .set_content_type(ContentType::html().0)
            .set_content_encoding(ContentEncoding::Brotli)
            .disable_content_disposition()
            .customize()
            .insert_header((header::VARY, "accept-encoding"));

        return Ok(Either::Left(page));
    }

    let page = web::block(move || -> io::Result<Vec<u8>> {
        let mut page = Vec::new();

        brotli_decompressor::Decompressor::new(File::open(file)?, 4096).read_to_end(&mut page)?;

        Ok(page)
    })
    .await??;

    Ok(Either::Right(
        HttpResponse::Ok()
            .content_type(ContentType::html())
            .insert_header((header::VARY, "accept-encoding"))
            .body(page),
    ))
}

#[cfg(test)]
mod tests {
    use super::*;
    use actix_web::{App, http::StatusCode, test, web::scope};

    fn statics() -> Data<StaticDir> {
        let root = Path::new(env!("CARGO_MANIFEST_DIR")).parent().unwrap();

        Data::new(StaticDir::new(root).unwrap())
    }

    #[actix_web::test]
    async fn docs_are_served_with_brotli_or_decompressed_for_other_clients() {
        let app = test::init_service(
            App::new()
                .app_data(statics())
                .service(scope("/docs").service(serve_docs)),
        )
        .await;
        let response = test::call_service(
            &app,
            test::TestRequest::get()
                .uri("/docs/champions/Aatrox")
                .insert_header((header::ACCEPT_ENCODING, "gzip, br"))
                .to_request(),
        )
        .await;
        assert_eq!(response.status(), StatusCode::OK);
        assert_eq!(
            response.headers().get(header::CONTENT_ENCODING).unwrap(),
            "br"
        );
        assert_eq!(
            response.headers().get(header::CONTENT_TYPE).unwrap(),
            "text/html; charset=utf-8"
        );
        let compressed = test::read_body(response).await;
        let mut page = Vec::new();
        brotli_decompressor::Decompressor::new(&compressed[..], 4096)
            .read_to_end(&mut page)
            .unwrap();
        assert!(page.starts_with(b"<!DOCTYPE html>"));

        let response = test::call_service(
            &app,
            test::TestRequest::get()
                .uri("/docs/champions/Aatrox")
                .insert_header((header::ACCEPT_ENCODING, "gzip"))
                .to_request(),
        )
        .await;
        assert_eq!(response.status(), StatusCode::OK);
        assert!(response.headers().get(header::CONTENT_ENCODING).is_none());
        assert_eq!(test::read_body(response).await, page);
    }

    #[actix_web::test]
    async fn unknown_docs_pages_return_not_found() {
        let app = test::init_service(
            App::new()
                .app_data(statics())
                .service(scope("/docs").service(serve_docs)),
        )
        .await;
        for uri in [
            "/docs/champions/NotAChampion",
            "/docs/spells/Aatrox",
            "/docs/champions/Aatrox.html",
            "/docs/champions/..%2F..%2FCargo",
        ] {
            let response =
                test::call_service(&app, test::TestRequest::get().uri(uri).to_request()).await;
            assert_eq!(response.status(), StatusCode::NOT_FOUND, "{uri}");
        }
    }

    #[actix_web::test]
    async fn images_are_served_from_the_static_folder() {
        let app =
            test::init_service(App::new().service(scope("/img").service(statics().images()))).await;
        for (uri, content_type) in [
            ("/img/champions/Aatrox.avif", "image/avif"),
            ("/img/centered/Aatrox_0.avif", "image/avif"),
            ("/img/stats/ability_power.svg", "image/svg+xml"),
        ] {
            let response =
                test::call_service(&app, test::TestRequest::get().uri(uri).to_request()).await;
            assert_eq!(response.status(), StatusCode::OK, "{uri}");
            assert_eq!(
                response.headers().get(header::CONTENT_TYPE).unwrap(),
                content_type
            );
        }
        for uri in ["/img/champions/Missing.avif", "/img/../Cargo.toml"] {
            let response =
                test::call_service(&app, test::TestRequest::get().uri(uri).to_request()).await;
            assert_eq!(response.status(), StatusCode::NOT_FOUND, "{uri}");
        }
    }
}
